      checks.push('testOrigin');
    } catch { errors.push('TEST_URL_INVALID'); }
  }
  if (environment !== undefined) {
    if (!['node', 'jsdom', 'happy-dom', 'browser'].includes(environment)) errors.push('TEST_ENVIRONMENT_UNKNOWN');
